const q = (r.topic || '').toLowerCase();
const topics = rows.map(function (x) { return x.topic; });
if (!q) {
  const about = rows.find(function (x) { return x.topic === 'about'; });
  return reply({ success: true, topics: topics, message: (about ? about.answer + ' ' : '') + 'I can help with pricing, hours, service area, maintenance plans, financing, and scheduling.' });
}
const stop = ['the', 'and', 'you', 'your', 'how', 'much', 'what', 'does', 'for', 'are', 'can', 'have', 'with', 'that', 'this', 'there', 'any', 'get', 'need', 'want', 'about', 'guys', 'offer'];
const ws = q.replace(/[^a-z0-9 ]/g, ' ').split(' ').filter(function (w) { return w.length > 2 && stop.indexOf(w) === -1; });
