  if (up.length === 1) return { target: up[0] };
  return { need: 'which', message: 'I see ' + up.length + ' upcoming appointments: ' + up.map(function (a) { return a.appointment_id + ', a ' + describe(a); }).join('; ') + '. Which one do you mean?' };
