const company = settings.company_name || 'HVAC demo';
const fail = function (need, message, extra) { const resp = { success: false, need: need, message: message }; if (extra) { Object.keys(extra).forEach(function (k) { resp[k] = extra[k]; }); } return [{ json: { write: false, response: resp } }]; };
