    water_leak: 'Turn the system off at the thermostat so it stops making more water.'
  };
  const safety = safetyMap[kind] || '';
  if (r.phone.length !== 10) return fail('phone', 'What is the best callback number, area code first?', { safety_message: safety });
  if (!r.address) return fail('address', 'What is the address where the technician is needed?', { safety_message: safety });
  const live = settings.live_transfer_enabled === 'true' && !!settings.transfer_number;
